import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback
import java.time.Instant

def flowFile = session.get()

if (flowFile == null) {
    return
}

try {
    def arrayPath = flowFile.getAttribute('PAYLOAD_ARRAY_NAME')
    def recordKeyPath = flowFile.getAttribute('ARRAY_ID')

    if (arrayPath == null || arrayPath.trim().isEmpty()) {
        throw new IllegalArgumentException(
            'PAYLOAD_ARRAY_NAME attribute is missing or empty'
        )
    }

    if (recordKeyPath == null || recordKeyPath.trim().isEmpty()) {
        throw new IllegalArgumentException(
            'ARRAY_ID attribute is missing or empty'
        )
    }

    def inputJson = ''

    session.read(flowFile, { inputStream ->
        inputJson = inputStream.getText('UTF-8')
    } as InputStreamCallback)

    def root = new JsonSlurper().parseText(inputJson)

    def normalizedArrayPath = arrayPath
        .trim()
        .replaceFirst(/^\\$\\.?/, '')

    if (normalizedArrayPath.isEmpty()) {
        throw new IllegalArgumentException(
            'PAYLOAD_ARRAY_NAME resolves to an empty path'
        )
    }

    def payloadArray = normalizedArrayPath
        .tokenize('.')
        .inject(root) { currentValue, pathPart ->
            if (currentValue instanceof Map) {
                return currentValue[pathPart]
            }

            return null
        }

    if (payloadArray == null) {
        throw new IllegalArgumentException(
            "Payload array '${arrayPath}' was not found"
        )
    }

    if (!(payloadArray instanceof Collection)) {
        throw new IllegalArgumentException(
            "Payload path '${arrayPath}' is not an array"
        )
    }

    def normalizedKeyPath = recordKeyPath
        .trim()
        .replaceFirst(/^\\$\\.?/, '')

    if (normalizedKeyPath.isEmpty()) {
        throw new IllegalArgumentException(
            'ARRAY_ID resolves to an empty path'
        )
    }

    def insertDateUtc = Instant.now().toString()
    def outputRecords = []

    payloadArray.eachWithIndex { feature, index ->

        if (!(feature instanceof Map)) {
            throw new IllegalArgumentException(
                "Array element at index ${index} is not a JSON object"
            )
        }

        def recordKey = normalizedKeyPath
            .tokenize('.')
            .inject(feature) { currentValue, pathPart ->
                if (currentValue instanceof Map) {
                    return currentValue[pathPart]
                }

                return null
            }

        if (recordKey == null ||
            recordKey.toString().trim().isEmpty()) {

            throw new IllegalArgumentException(
                "Key path '${recordKeyPath}' was not found " +
                "in array element at index ${index}"
            )
        }

        outputRecords.add([
            KEY        : recordKey.toString(),
            PAYLOAD    : JsonOutput.toJson(feature),
            INSERT_DATE: insertDateUtc
        ])
    }

    flowFile = session.write(flowFile, { outputStream ->
        outputStream.write(
            JsonOutput.toJson(outputRecords).getBytes('UTF-8')
        )
    } as OutputStreamCallback)

    flowFile = session.putAllAttributes(flowFile, [
        'mime.type'                   : 'application/json',
        'payload.array.path'          : arrayPath,
        'payload.record.key.path'     : recordKeyPath,
        'transformed.record.count'    : outputRecords.size().toString(),
        'transformation.timestamp.utc': insertDateUtc
    ])

    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error(
        "Failed to transform API payload: ${e.message}",
        e
    )

    flowFile = session.putAllAttributes(flowFile, [
        'transform.error.class'  : e.class.name,
        'transform.error.message': e.message ?: 'Unknown transformation error'
    ])

    session.transfer(flowFile, REL_FAILURE)
}

import groovy.json.JsonSlurper
import groovy.xml.XmlSlurper

def flowFile = session.get()
if (!flowFile) return

def dataType = flowFile.getAttribute('DATA_TYPE') ?: 'JSON'
def arrayName = flowFile.getAttribute('PAYLOAD_ARRAY_NAME')

def text = ''
session.read(flowFile, { is -> text = is.getText('UTF-8') } as InputStreamCallback)

def count = 0

if (dataType == 'XML') {
    def current = new XmlSlurper().parseText(text.trim())
    arrayName.split('\\.').each { key -> current = current."${key}" }
    count = current.size()
} else {
    def current = new JsonSlurper().parseText(text)
    for (key in arrayName.split('\\.')) {
        if (!(current instanceof Map) || !current.containsKey(key)) { current = null; break }
        current = current[key]
    }
    count = (current instanceof List) ? current.size() : (current != null ? 1 : 0)
}

def previousTotal = (flowFile.getAttribute('TOTAL_RECORD_COUNT') ?: '0') as Integer
def runningTotal = previousTotal + count

flowFile = session.putAttribute(flowFile, 'RECORD_COUNT', count.toString())
flowFile = session.putAttribute(flowFile, 'TOTAL_RECORD_COUNT', runningTotal.toString())

session.transfer(flowFile, REL_SUCCESS)

